   208:    //  ★★★ 这里曾经是全项目最阴的一个 bug，务必保留这段说明 ★★★
   209:    //
   210:    //  旧写法是 while (true && rclcpp::ok()) 死等一个完整帧，只有
   211:    //  header1==0xB5 && header2==0x5B 且帧体读齐 时才 break。
   212:    //
   213:    //  问题出在"串口安静的时候"（裁判板没上电 / 线松了 / 就是没在发数据）：
   214:    //      ser.available() 恒为 0，header1/header2 是【未初始化】的栈变量，
   215:    //      这个循环永远不会 break，于是 ——
   216:    //        · CPU 直接跑满（实测 102%）
   217:    //        · 更要命：run() 里那个 10Hz 循环被彻底卡死，
   218:    //          rclcpp::spin_some() 再也不会被调用
   219:    //          → 所有订阅回调失效 → 开火指令收不到 → 激光不亮
   220:    //      而 ros2 topic info 依然显示 Subscription count: 1，
   221:    //      看起来一切正常，排查时极具迷惑性。
   222:    //
   223:    //  修法：改成【有界 + 非阻塞】——
   224:    //        · 串口没数据立刻收工，把控制权还给 run() 去 spin
   225:    //        · 每次最多处理 8 帧，防止对端灌数据时又把自己卡住
   226:    //        · 半帧状态靠成员 previousHeader2 跨调用保留
   227:    // =====================================================================
   228:    for (int guard = 0; guard < 8; ++guard)
   229:    {
   230:        if (ser.available() <= 0)
   231:        {
   232:            return;                     // 没数据就立刻让出，绝不空转
   233:        }
   234:
   235:        uint8_t header1 = 0, header2 = 0;
   236:
   237:        if (previousHeader2 == 0xB5)
   238:        {
   239:            header1 = previousHeader2;
   240:        }
   241:        else
   242:        {
   243:            while (ser.available() > 0)
   244:            {
   245:                ser.read(&header1, 1);
   246:                if (header1 == 0xB5)
   247:                    break;
   248:            }
   249:        }
   250:
   251:        if (ser.available() <= 0)
   252:        {
   253:            return;                     // 只有帧头，帧体下次再读
   254:        }
   255:        ser.read(&header2, 1);
   256:        previousHeader2 = header2;
   257:
   258:        if (header1 != 0xB5 || header2 != 0x5B)
   259:        {
   260:            continue;                   // 不是帧头，接着找
   261:        }
   262:
   263:        if (ser.available() <= 0)
   264:        {
   265:            return;                     // 长度字节还没到
   266:        }
   267:        uint8_t dataLength;
   268:        ser.read(&dataLength, 1);
   269:
   270:        if (ser.available() < static_cast<size_t>(dataLength))
   271:        {
   272:            return;                     // 帧体没齐，等下个周期凑齐
   273:        }
