/* ============================================================
   ★ 总体布局：左侧「调参侧边栏」 + 右侧「主区」
   ------------------------------------------------------------
     ┌──────────────┬──────────────────────────────────┐
     │ 侧边栏(调参) │  大窗口 (图传画面 ⇄ 轨迹地图)      │
     │ · 遥控 / 调参 │  ────────────────────────────────│
     │ · 可拖拽调宽  │  [图传画面] [轨迹地图]  ← 切换    │
     │ · 内部独立滚动│  ────────────────────────────────│
     │ · 8 组参数全览 │  常用参数（一键调节 + 应用）     │
     └──────────────┴──────────────────────────────────┘

   为什么这么排（三个理由）：
     1. 调参是"高频、需纵览"的操作 —— 放侧边栏后 8 组参数纵向一列，
        滚动条永远在右手边，不会出现"参数被挤到看不见"的错觉。
     2. 画面是"高频、要看清"的东西 —— 主区整块给它，视频/地图
        叠放在同一容器里切换，窗口利用率 100%（不再左右分屏各占一半）。
     3. 常用参数单独提到主区底部：出车前最常动的几个（车速/俯仰/
        扫描速度/弹药）不用在侧边栏里翻找。
   ============================================================ */
.app{
  position:relative;z-index:1;
  height:100vh;overflow:hidden;
  display:grid;
  /* 侧边栏宽度由 JS 拖拽写入 --side-w；夹在 300~620 之间 */
  grid-template-columns:var(--side-w,392px) 5px 1fr;
}
.app.side-collapsed{grid-template-columns:0 0 1fr;}

/* 侧边栏：折叠时让出一条"展开条"，否则用户没法把它叫回来 */
.sidepeek{
  position:absolute;left:0;top:0;bottom:0;width:28px;z-index:6;
  display:none;align-items:center;justify-content:center;
  background:var(--panel);border-right:1px solid var(--line);
  color:var(--fg-dim);cursor:pointer;user-select:none;
  writing-mode:vertical-rl;letter-spacing:3px;font-size:12px;
}
.sidepeek:hover{color:var(--fg);background:var(--panel2);}
.app.side-collapsed .sidepeek{display:flex;}

/* ---------- 侧边栏 ---------- */
.sidebar{
  display:flex;flex-direction:column;min-height:0;min-width:0;
  background:var(--panel);border-right:1px solid var(--line);
  overflow:hidden;
}
.sidehead{
  flex:0 0 auto;display:flex;align-items:center;gap:8px;
  padding:9px 12px;border-bottom:1px solid var(--line);
  background:linear-gradient(180deg,var(--panel2),var(--panel));
}
.sidehead .ttl{font-weight:700;font-size:13.5px;letter-spacing:.5px;}
.sidehead .sub{color:var(--fg-mute);font-size:11px;}

.sidefilter{flex:0 0 auto;padding:8px 10px 0;}
.sidefilter input{
  width:100%;background:#0d131b;border:1px solid var(--line2);border-radius:7px;
  color:var(--fg);font:inherit;font-size:12px;padding:5px 9px;
}
.sidefilter input:focus{outline:none;border-color:var(--accent);
  box-shadow:0 0 0 2px rgba(34,211,238,.13);}

/* ★ 独立滚动容器：保证遥控器与 8 组参数都能完整访问到 */
.sidescroll{
  flex:1 1 auto;min-height:0;overflow-y:auto;overflow-x:hidden;
  overscroll-behavior:contain;
  scrollbar-width:thin;scrollbar-color:#3a4c66 transparent;
}
.sidescroll::-webkit-scrollbar{width:11px;}
.sidescroll::-webkit-scrollbar-track{background:rgba(255,255,255,.035);border-radius:6px;}
.sidescroll::-webkit-scrollbar-thumb{background:#3a4c66;border-radius:6px;
  border:2px solid var(--panel);}
.sidescroll::-webkit-scrollbar-thumb:hover{background:#4d6688;}

.sidefoot{
  flex:0 0 auto;display:flex;align-items:center;gap:7px;flex-wrap:wrap;
  padding:8px 10px;border-top:1px solid var(--line);background:var(--panel2);
}

/* 拖拽调宽把手 */
.resizer{cursor:col-resize;background:transparent;}
.resizer:hover,.resizer.dragging{background:rgba(34,211,238,.28);}

/* ---------- 主区 ---------- */
.main{
  display:flex;flex-direction:column;min-width:0;min-height:0;gap:0;
  padding:10px;overflow:hidden;
}

/* 大窗口：视频与地图叠放在同一容器，靠 .on 决定显示谁 */
.viewwrap{
  position:relative;flex:1 1 auto;min-height:0;
  border:1px solid var(--line);border-radius:var(--radius);
  background:#05080b;overflow:hidden;
}
.cell{
  position:absolute;inset:0;
  display:none;flex-direction:column;min-width:0;min-height:0;
  background:var(--panel);overflow:hidden;
}
.cell.on{display:flex;}

/* 画面切换按钮条 */
.viewswitch{
  flex:0 0 auto;display:flex;align-items:center;gap:8px;
  padding:9px 2px 0;
}
.vsbtn{
  display:inline-flex;align-items:center;gap:6px;
  padding:7px 16px;border-radius:9px;cursor:pointer;
  border:1px solid var(--line2);background:#1a2330;color:var(--fg-dim);
  font-size:12.5px;font-weight:600;transition:all .14s;
}
.vsbtn:hover{background:#22303f;color:var(--fg);border-color:#3d4f66;}
.vsbtn.on{background:var(--accent-dim);border-color:var(--accent);color:#eafcff;}

/* 常用参数条 */
.quickset{
  flex:0 0 auto;margin-top:8px;
  border:1px solid var(--line);border-radius:var(--radius);
  background:var(--panel);overflow:hidden;
}
.qshead{
  display:flex;align-items:center;gap:9px;padding:6px 11px;
  background:linear-gradient(180deg,var(--panel2),var(--panel));
  border-bottom:1px solid var(--line);
  font-weight:600;font-size:12.5px;
}
.qsgrid{
  display:grid;grid-template-columns:repeat(auto-fit,minmax(268px,1fr));
  gap:4px 14px;padding:8px 11px;
  max-height:26vh;overflow-y:auto;overscroll-behavior:contain;
  scrollbar-width:thin;scrollbar-color:#3a4c66 transparent;
}
.qsgrid::-webkit-scrollbar{width:10px;}
.qsgrid::-webkit-scrollbar-thumb{background:#3a4c66;border-radius:6px;
  border:2px solid var(--panel);}
.qsit{display:flex;align-items:center;gap:7px;min-height:24px;}
.qsit .k{flex:0 0 auto;min-width:96px;max-width:96px;font-size:12px;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.qsit .u{flex:0 0 auto;color:var(--fg-mute);font-size:10.5px;}
.qsit input[type=range]{flex:1 1 auto;min-width:48px;height:16px;accent-color:var(--accent);}
.qsit input[type=number]{flex:0 0 auto;width:66px;
  background:#0d131b;border:1px solid var(--line2);border-radius:6px;
  color:var(--fg);font:inherit;font-size:12px;padding:3px 7px;
  font-variant-numeric:tabular-nums;}
.qsit input[type=number]:focus{outline:none;border-color:var(--accent);}
.qsit.dirty .k{color:var(--warn);font-weight:600;}
.qsfoot{
  display:flex;align-items:center;gap:9px;
  padding:7px 11px;border-top:1px solid var(--line);background:var(--panel2);
}

/* 窄屏：侧边栏默认折叠，保证主区还能用 */
@media (max-width:900px){
  .app{grid-template-columns:0 0 1fr;}
  .sidebar{opacity:0;pointer-events:none;}
  .app:not(.side-collapsed) .sidepeek{display:flex;}
}
