    const row = box.querySelector('.qsit[data-g="' + g.id + '"][data-key="' + it.key + '"]');
    if (it.type === 'bool'){
      main.addEventListener('change', () => { setDirty(g, it, main.checked); markQuick(); });
    } else {
      rng.addEventListener('input', () => { main.value = rng.value; setDirty(g, it, parseFloat(rng.value)); markQuick(); });
      main.addEventListener('input', () => {
        const x = parseFloat(main.value);
        if (!isNaN(x)){ rng.value = Math.min(it.max, Math.max(it.min, x)); setDirty(g, it, x); markQuick(); }
      });
    }
  });
  markQuick();
}

function quickDirtyN(){
  let n = 0;
  QUICK.forEach(({g}) => { if (DIRTY[g.id]) n += Object.keys(DIRTY[g.id]).length; });
  return n;
