    if (row) row.classList.toggle('dirty', !!(DIRTY[g.id] && (it.key in DIRTY[g.id])));
  });
  const n = quickDirtyN();
  $('qsApply').disabled = (n === 0);
  $('qsApply').textContent = n ? ('应用改动 (' + n + ')') : '应用改动';
}

