  if (!Object.keys(changes).length) return;
  btn.classList.add('spin'); msg.className='applymsg'; msg.textContent='写入中…';
  let res;
  try{
    const r = await fetch(CONFIG_URL, {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({changes})});
    res = await r.json();
  }catch(err){ btn.classList.remove('spin'); msg.className='applymsg err'; msg.textContent='请求失败：'+err.message; return; }
  btn.classList.remove('spin');
  if (!res.ok){
    msg.className='applymsg err';
    msg.textContent = (res.errors || [res.error||'未知错误']).join('\n') + (res.hint ? '\n'+res.hint : '');
