  let lines = ['已写入：' + res.written.join('；')];
  (res.restarts||[]).forEach(rr => { lines.push((rr.ok?'✅ ':'❌ ')+'重启 '+(RESTART_CN[rr.node]||rr.node)+' '+(rr.ok?'成功':'失败')); });
  msg.className='applymsg ok'; msg.textContent = lines.join('\n');
  Object.keys(changes).forEach(sec => {});   // 成功后才清
  Object.keys(DIRTY).forEach(k => delete DIRTY[k]);
  if (res.snapshot && res.snapshot.ok){ CFD = res.snapshot; renderConfig(); }
  else { await loadConfig(); }
  renderQuick();
});

