const SIDE_KEY = 'dzrobot_side_v1';
function loadSide(){
  try{ return JSON.parse(localStorage.getItem(SIDE_KEY) || '{}') || {}; }
  catch(e){ return {}; }
}
function saveSide(o){ try{ localStorage.setItem(SIDE_KEY, JSON.stringify(o)); }catch(e){} }

function setSide(on){
  appEl.classList.toggle('side-collapsed', on);
  $('btnSideFold').textContent = on ? '《 展开' : '》 收起';
