(function(){
  const rz = $('resizer');
  let dragging = false;
  const curW = () => parseInt(getComputedStyle(document.documentElement)
                        .getPropertyValue('--side-w')) || 392;
  rz.addEventListener('pointerdown', e => {
    dragging = true; rz.classList.add('dragging');
    try{ rz.setPointerCapture(e.pointerId); }catch(err){}
  });
  rz.addEventListener('pointermove', e => {
    if (!dragging) return;
    const w = Math.min(620, Math.max(300, e.clientX));
    document.documentElement.style.setProperty('--side-w', w + 'px');
  });
  const end = () => {
    if (!dragging) return;
    dragging = false; rz.classList.remove('dragging');
    const s = loadSide(); s.w = curW(); saveSide(s);
  };
