    } else {
      ctl = '<input type="range" id="' + id + '_r" min="' + it.min + '" max="' + it.max
          + '" step="' + it.step + '" value="' + v + '">'
          + '<input type="number" id="' + id + '" min="' + it.min + '" max="' + it.max
          + '" step="' + it.step + '" value="' + v + '">';
    }
    html += '<div class="qsit" data-g="' + g.id + '" data-key="' + it.key + '"'
          +  ' title="' + (it.hint || it.label) + '">'
          +  '<span class="k">' + it.label + '</span>' + u + ctl + '</div>';
  });
  box.innerHTML = html;

  QUICK.forEach(function(f){
    const g = f.g, it = f.it, id = 'q_' + g.id + '_' + it.key;
    const main = $(id), rng = $(id + '_r');
    if (!main) return;
    if (it.type === 'bool'){
      main.addEventListener('change', function(){ setDirty(g, it, main.checked); markQuick(); });
    } else {
      rng.addEventListener('input', function(){
        main.value = rng.value;
        setDirty(g, it, parseFloat(rng.value)); markQuick();
      });
      main.addEventListener('input', function(){
        const x = parseFloat(main.value);
        if (!isNaN(x)){
          rng.value = Math.min(it.max, Math.max(it.min, x));
          setDirty(g, it, x); markQuick();
        }
      });
    }
  });
  markQuick();
}

function markQuick(){
  QUICK.forEach(function(f){
    const row = document.querySelector('#qsGrid .qsit[data-g="' + f.g.id + '"][data-key="' + f.it.key + '"]');
    if (row) row.classList.toggle('dirty', !!(DIRTY[f.g.id] && (f.it.key in DIRTY[f.g.id])));
  });
  let n = 0;
  QUICK.forEach(function(f){ if (DIRTY[f.g.id]) n += Object.keys(DIRTY[f.g.id]).length; });
  const btn = $('qsApply');
  btn.disabled = (n === 0);
  btn.textContent = n ? ('应用改动 (' + n + ')') : '应用改动';
}

$('qsApply').addEventListener('click', async function(){
  const btn = $('qsApply'), msg = $('qsMsg');
  const changes = {};
  QUICK.forEach(function(f){
    if (DIRTY[f.g.id]){
      changes[f.g.section] = Object.assign({}, changes[f.g.section] || {}, DIRTY[f.g.id]);
    }
  });
  if (!Object.keys(changes).length) return;
  btn.classList.add('spin');
  msg.className = 'applymsg';
  msg.textContent = '写入中…';
  let res;
  try{
    const r = await fetch(CONFIG_URL, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({changes: changes}),
    });
    res = await r.json();
  }catch(err){
    btn.classList.remove('spin');
    msg.className = 'applymsg err';
    msg.textContent = '请求失败：' + err.message;
    return;
  }
  btn.classList.remove('spin');
  if (!res.ok){
    msg.className = 'applymsg err';
    msg.textContent = (res.errors || [res.error || '未知错误']).join('\n')
                    + (res.hint ? '\n' + res.hint : '');
    return;
  }
  let lines = ['已写入：' + res.written.join('；')];
  (res.restarts || []).forEach(function(rr){
    lines.push((rr.ok ? '✅ ' : '❌ ') + '重启 ' + (RESTART_CN[rr.node] || rr.node)
               + ' ' + (rr.ok ? '成功' : '失败'));
  });
  msg.className = 'applymsg ok';
  msg.textContent = lines.join('\n');
  Object.keys(DIRTY).forEach(k => delete DIRTY[k]);
  if (res.snapshot && res.snapshot.ok){ CFD = res.snapshot; renderConfig(); }
  else { await loadConfig(); }
  renderQuick();
});

$('qsReset').addEventListener('click', async function(){
  Object.keys(DIRTY).forEach(k => delete DIRTY[k]);
  $('qsMsg').className = 'applymsg';
  $('qsMsg').textContent = '';
  await loadConfig();
  renderQuick();
});

/* ---------- 4. 参数搜索过滤（侧边栏 8 组 + 主区常用参数） ---------- */
$('cfgSearch').addEventListener('input', function(e){
  const q = e.target.value.trim().toLowerCase();
  document.querySelectorAll('#cfgGroups .grp').forEach(function(card){
    if (!q){ card.style.display = ''; return; }
    const hit = card.textContent.toLowerCase().indexOf(q) >= 0;
    card.style.display = hit ? '' : 'none';
    if (hit) card.classList.remove('collapsed');   // 命中的分组自动展开
  });
  QUICK.forEach(function(f){
    const row = document.querySelector('#qsGrid .qsit[data-g="' + f.g.id + '"][data-key="' + f.it.key + '"]');
    if (!row) return;
    if (!q){ row.style.display = ''; return; }
    const hay = (f.it.label + ' ' + f.it.key + ' ' + (f.it.hint || '')).toLowerCase();
    row.style.display = (hay.indexOf(q) >= 0) ? '' : 'none';
  });
});
