   330:// 竖直轴刻度钳位（下位机强制 950~2400）
   331:int turn_on_robot::clampPitchTick(int tick) const
   332:{
   333:  if (tick < gimbal_pitch_tick_min_)
   334:  {
   335:    return gimbal_pitch_tick_min_;
   336:  }
   337:  if (tick > gimbal_pitch_tick_max_)
   338:  {
   339:    return gimbal_pitch_tick_max_;
   340:  }
   341:  return tick;
   342:}
   343:
   344:// ★P0-1 把水平轴限制在【扫描范围】内，而不是硬件极限(100~3995)。
   345://   实测故障：车体偏航时跟踪会一路把云台推到 3988(≈170.6°)，远超 ±90° 扫描范围，
   346://   最后撞在机械限位上堵转，表现为"云台定住不动"。
   347:int turn_on_robot::clampYawToScan(int tick) const
   348:{
   349:  const int t1 = clampYawTick(gimbal_center_tick_ + static_cast<int>(std::lround(
   350:      scan_yaw_min_deg_ * yaw_ticks_per_deg_ * yaw_deg_sign_)));
   351:  const int t2 = clampYawTick(gimbal_center_tick_ + static_cast<int>(std::lround(
   352:      scan_yaw_max_deg_ * yaw_ticks_per_deg_ * yaw_deg_sign_)));
   353:  const int lo = std::min(t1, t2);
   354:  const int hi = std::max(t1, t2);
   355:  return std::max(lo, std::min(hi, tick));
   356:}
   357:
   358:// ★P0-1 竖直轴同理：限制在扫描俯仰范围(层角度 + 整体偏移)内
   359:int turn_on_robot::clampPitchToScan(int tick) const
   360:{
   361:  double lo_deg = scan_pitch_offset_deg_;
   362:  double hi_deg = scan_pitch_offset_deg_;
   363:  if (!scan_pitch_levels_deg_.empty())
   364:  {
   365:    lo_deg += *std::min_element(scan_pitch_levels_deg_.begin(), scan_pitch_levels_deg_.end());
   366:    hi_deg += *std::max_element(scan_pitch_levels_deg_.begin(), scan_pitch_levels_deg_.end());
   367:  }
   368:  // ★关键：在扫描俯仰范围之外再留出跟踪修正余量。
   369:  //   踩过的坑：scan_pitch_levels 只剩一层时(如 [0.0]，即"只做水平扫描")，
